function expandAntiCollisions(base) {
  const extra = [];
  const commissionVsChannel = [
    "top 5 comisionistas",
    "ranking de comisionistas",
    "venta de comisionistas",
    "mezcla casa comisionista",
    "clientes del canal comisionista",
    "participación comisionista",
    "lista de comisionistas",
    "quiénes son comisionistas",
    "comisionistas que más compraron",
    "filtra comisionistas",
  ];
  for (const q of commissionVsChannel) extra.push([q, null, "IGF_COMMISSION_CURRENT"]);
  const discountVsCommission = [
    "qué descuento tenemos",
    "cuánto descuento tenemos",
    "el descuento actual",
    "descuento a la fecha",
    "nuestro descuento",
  ];
  for (const q of discountVsCommission) extra.push([q, "IGF_DISCOUNT_CURRENT", "IGF_COMMISSION_CURRENT"]);
  const commissionVsDiscount = [
    "cuánto tenemos de comisión",
    "cuál es la comisión",
    "la comisión actual",
    "comisión a la fecha",
    "nuestra comisión",
  ];
  for (const q of commissionVsDiscount) extra.push([q, "IGF_COMMISSION_CURRENT", "IGF_DISCOUNT_CURRENT"]);
  const hgVsPct = [
    "qué HG tenemos",
    "cuál es el HG",
    "HG actual",
    "qué HG$ tenemos",
    "el HG de este mes",
  ];
  for (const q of hgVsPct) extra.push([q, "IGF_HG_CURRENT", "IGF_PROFITABILITY"]);
  const corpVsOp = [
    "cuánto es el gasto corporativo",
    "gasto corporativo actual",
    "gastos corporativos de este mes",
    "el corporativo que tenemos",
    "apoyos corporativos actuales",
  ];
  for (const q of corpVsOp) extra.push([q, "IGF_CORPORATE_EXPENSE_CURRENT", "IGF_HG_CURRENT"]);
  const opVsCorp = [
    "gasto operativo",
    "gastos operativos",
    "el gasto operativo de planta",
    "operativos del mes",
    "cuánto es el gasto operativo",
  ];
  for (const q of opVsCorp) extra.push([q, null, "IGF_CORPORATE_EXPENSE_CURRENT"]);
  const rentVsMargin = [
    "cuál es la rentabilidad",
    "qué rentabilidad tenemos",
    "dame la rentabilidad",
    "rentabilidad IGF",
    "la rentabilidad puntual",
  ];
  for (const q of rentVsMargin) extra.push([q, "IGF_PROFITABILITY", "IGF_DISCOUNT_CURRENT"]);
  const marginVsRent = [
    "qué margen tenemos",
    "cuál es el margen",
    "margen actual",
    "el margen de planta",
    "margen IGF",
  ];
  for (const q of marginVsRent) extra.push([q, null, "IGF_PROFITABILITY"]);
  const finalVsOp = [
    "cuál es el resultado final",
    "resultado final de planta",
    "el resultado final IGF",
    "dame el resultado final",
    "resultado final actual",
  ];
  for (const q of finalVsOp) extra.push([q, null, "IGF_PROFITABILITY"]);
  const leftVsDown = [
    "cuánto dejamos de vender por ellos",
    "el agregado de ellos",
    "esos clientes",
    "los anteriores",
    "ese conjunto",
  ];
  for (const q of leftVsDown) extra.push([q, "RESULT_SET_PRONOUN_REFERENCE", "IGF_DISCOUNT_CURRENT"]);
  const downVsPronoun = [
    "los que disminuyeron",
    "quiénes disminuyeron",
    "clientes que bajaron",
    "disminuyeron en septiembre",
    "lista de los que disminuyeron",
  ];
  for (const q of downVsPronoun) extra.push([q, null, "RESULT_SET_PRONOUN_REFERENCE"]);
  const domainSwitch = [
    "y los comisionistas",
    "ahora los comisionistas",
    "cambia a comisionistas",
    "dame comisionistas",
    "abre pronóstico",
  ];
  for (const q of domainSwitch) extra.push([q, null, "RESULT_SET_PRONOUN_REFERENCE"]);
  for (let i = 1; i <= 23; i += 1) {
    extra.push([`comisión actual variante ${i}`, "IGF_COMMISSION_CURRENT", "IGF_DISCOUNT_CURRENT"]);
    extra.push([`descuento actual variante ${i}`, "IGF_DISCOUNT_CURRENT", "IGF_COMMISSION_CURRENT"]);
    extra.push([`top comisionistas variante ${i}`, null, "IGF_COMMISSION_CURRENT"]);
    extra.push([`ellos volumen variante ${i}`, "RESULT_SET_PRONOUN_REFERENCE", "IGF_HG_CURRENT"]);
  }
  return [...base, ...extra];
}

